const r = $input.first().json.r;
const hora = s => new Date(s).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Sao_Paulo' });

const agenda = r.agenda.length
  ? r.agenda.map(e => `  ${hora(e.inicio)}  ${e.titulo}` +
      (e.local ? ` — ${e.local}` : '') +
      (e.bairro ? ` (${e.bairro})` : '') +
      `   [${e.onde}]`).join('\n')
  : '  (nada marcado)';

// O link vem PRONTO para a Mariana clicar. Quem manda a mensagem é ela, uma
// conversa por vez: a Plataforma WhatsApp Business proíbe campanha política e
// a lei eleitoral veda disparo em massa. Este fluxo é copiloto, não remetente.
const gente = r.novos_apoiadores.length
  ? r.novos_apoiadores.map(p => `  ${p.nome} — ${p.bairro}\n    ${p.link}` +
      (p.ajuda && p.ajuda.length ? `\n    quer ajudar com: ${p.ajuda.join(', ')}` : '') +
      (p.recado ? `\n    recado: "${p.recado}"` : '')).join('\n\n')
  : '  (ninguém novo)';

const texto = [
  'AGENDA DE AMANHÃ',
  agenda,
  '',
  `QUEM SE CADASTROU E AINDA NÃO FOI CONTATADO (${r.a_contatar} no total)`,
  gente,
  '',
  r.sairam_7d ? `${r.sairam_7d} pessoa(s) pediram para sair nos últimos 7 dias — já estão fora da lista.` : '',
  '',
  'Clique no link de cada pessoa e fale com ela pelo WhatsApp Business, uma por vez.',
  'Depois de falar, marque no painel para ela sair desta lista.',
].filter(Boolean).join('\n');

return [{ json: { texto, assunto: `[Vilma] amanhã: ${r.agenda.length} compromisso(s) · ${r.novos_apoiadores.length} pessoa(s) para chamar` } }];
